    {
      "name": "DFinsupp.card_Iic",
      "module_name": "Mathlib.Data.DFinsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : DecidableEq ι] [inst_1 : (i : ι) → DecidableEq (α i)]\n  [inst_2 : (i : ι) → AddCommMonoid (α i)] [inst_3 : (i : ι) → PartialOrder (α i)]\n  [inst_4 : ∀ (i : ι), CanonicallyOrderedAdd (α i)] [inst_5 : (i : ι) → OrderBot (α i)]\n  [inst_6 : (i : ι) → LocallyFiniteOrder (α i)] (f : Π₀ (i : ι), α i),\n  (Finset.Iic f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card"
    },
    {
      "name": "Finsupp.card_Iic",
      "module_name": "Mathlib.Data.Finsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [inst_2 : CanonicallyOrderedAdd α]\n  [inst_3 : OrderBot α] [inst_4 : LocallyFiniteOrder α] [inst_5 : DecidableEq ι] [inst_6 : DecidableEq α] (f : ι →₀ α),\n  (Finset.Iic f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card"
    },
    {
      "name": "DFinsupp.card_pi",
      "module_name": "Mathlib.Data.DFinsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : (i : ι) → Zero (α i)] [inst_1 : DecidableEq ι]\n  [inst_2 : (i : ι) → DecidableEq (α i)] (f : Π₀ (i : ι), Finset (α i)), f.pi.card = f.prod fun i => ↑(f i).card"
    },
    {
      "name": "Finsupp.card_Icc",
      "module_name": "Mathlib.Data.Finsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : PartialOrder α] [inst_1 : Zero α] [inst_2 : LocallyFiniteOrder α]\n  [inst_3 : DecidableEq ι] [inst_4 : DecidableEq α] (f g : ι →₀ α),\n  (Finset.Icc f g).card = ∏ i ∈ f.support ∪ g.support, (Finset.Icc (f i) (g i)).card"
    },
    {
      "name": "Finsupp.card_Iio",
      "module_name": "Mathlib.Data.Finsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [inst_2 : CanonicallyOrderedAdd α]\n  [inst_3 : OrderBot α] [inst_4 : LocallyFiniteOrder α] [inst_5 : DecidableEq ι] [inst_6 : DecidableEq α] (f : ι →₀ α),\n  (Finset.Iio f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card - 1"
    },
    {
      "name": "Finsupp.card_pi",
      "module_name": "Mathlib.Data.Finset.Finsupp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : Zero α] (f : ι →₀ Finset α), f.pi.card = f.prod fun i => ↑(f i).card"
    },
    {
      "name": "Pi.card_Iic",
      "module_name": "Mathlib.Data.Pi.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : Fintype ι] [inst_1 : DecidableEq ι] [inst_2 : (i : ι) → DecidableEq (α i)]\n  [inst_3 : (i : ι) → PartialOrder (α i)] [inst_4 : (i : ι) → LocallyFiniteOrderBot (α i)] (b : (i : ι) → α i),\n  (Finset.Iic b).card = ∏ i, (Finset.Iic (b i)).card"
    },
    {
      "name": "DFinsupp.card_Iio",
      "module_name": "Mathlib.Data.DFinsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : DecidableEq ι] [inst_1 : (i : ι) → DecidableEq (α i)]\n  [inst_2 : (i : ι) → AddCommMonoid (α i)] [inst_3 : (i : ι) → PartialOrder (α i)]\n  [inst_4 : ∀ (i : ι), CanonicallyOrderedAdd (α i)] [inst_5 : (i : ι) → OrderBot (α i)]\n  [inst_6 : (i : ι) → LocallyFiniteOrder (α i)] (f : Π₀ (i : ι), α i),\n  (Finset.Iio f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card - 1"
    }
  ]
}
